      for i in plVotes
      {
         if NOT Send(self,@IsLegalJusticar,#candidate=Nth(i,2))
         {
            continue; 
         }

         bFound = FALSE;

         for j in lTallied
         {
            if nth(i,2) = first(j)          
            {
               setnth(j,2,(nth(j,2)+1));
               bFound = TRUE;
            }            
         }

         if not bFound
         {
            lTallied = cons([nth(i,2),1],lTallied);
         }
      }

      if lTallied = $
      {
         Send(self,@SayToOne,#target=who,#message_rsc=barloque_clerk_tally_tied,#type1=STRING_RESOURCE);

         return;
