      oHighest = $;
      iHighestCount = 0;      
      bTie = FALSE;

      for i in lTallied
      {
         if Nth(i,2) = iHighestCount
         {
            bTie = TRUE;
         }

         if Nth(i,2) > iHighestCount
         {
