                 #parm1=Send(oVote,@GetTrueName),#type1=STRING_RESOURCE);

            SetNth(i,2,oVote);

            bFound = TRUE;
         }
      }

      if NOT bFound
      {
         Send(self,@SayToOne,#message_rsc=barloqueclerk_vote_noted,#target=voter,
