      {
         if col_diff > 0
         {
            iDir = 2;
         }
         else
         {
            iDir = 6;
         }
      }
      else
      {
         iAtan = 1000 * col_diff / row_diff;
      }


      if row_diff > 0 
      {
         if iAtan >= 2414
         {
            iDir = 2;
         }
         else
         {
            if iAtan >= 414
            {
               iDir = 1;
            }
            else
            {
               if iAtan >= -414
               {
                  iDir = 0;
               }
               else
               {
                  if iAtan >= -2414
                  {
                     iDir = 7;
                  }
                  else
                  {
                     iDir = 6;
                  }
               }
            }
         }
      }


      if row_diff < 0 
      {
         if iAtan >= 2414
         {
            iDir = 6;
         }
         else
         {
            if iAtan >= 414
            {
               iDir = 5;
            }
            else
            {
               if iAtan >= -414
               {
                  iDir = 4;
               }
               else
               {
                  if iAtan >= -2414
                  {
                     iDir = 3;
                  }
                  else
                  {
                     iDir = 2;
                  }
               }
            }
         }
      }

      iTry_dir = iDir;
      if Send(self,@TryDirection,#dir=iTry_dir,
         #face_target=face_target,#face_away=face_away) 
      {

         piState = piState & ESTATE_ZERO_MASK;

         return TRUE;
      }
      else
      {


         if piState & ESTATE_AVOIDING
         {
            if piState & ESTATE_CLOCKWISE
            {

               iIter = 321;
            }
            else
            {

               iIter = 567;
            }
         }
         else
         {



            if row_diff mod 2
            {
               iIter = 536271;
            }
            else
            {
               iIter = 352617;
            }
         }








         while iIter > 0
         {
            i = iIter mod 10;
            iTry_dir = ( iDir + i ) mod 8;
            if Send(self,@TryDirection,#dir=iTry_dir,#face_target=face_target,
