      for i in lRank_names
      {
         AddPacket(STRING_RESOURCE,i);
      }


      lMembers = Send(poGuild,@GetMemberList);


      for i in lMembers
      {
         if First(i) = self
         {
            if Nth(i,3) = $
            {

               AddPacket(4,0);
            }
            else
            {
               AddPacket(4,Nth(i,3));
            }
         }
      }

      AddPacket(2,Length(lMembers));
      for i in lMembers
      {
         AddPacket(4,First(i));
         AddPacket(STRING_RESOURCE,Send(First(i),@GetTrueName));
         AddPacket(1,Nth(i,2));
         AddPacket(1,Send(First(i),@GetGender));
