         iRow = Send(what,@GetSaveRow);
         iCol = Send(what,@GetSaveCol);
         iFineRow = Send(what,@GetSaveFineRow);
         iFineCol = Send(what,@GetSaveFineCol);

         logged_off = TRUE;
