         iRow = Send(what,@GetRow);
         iCol = Send(what,@GetCol);
         iFineRow = Send(what,@GetFineRow);
         iFineCol = Send(what,@GetFineCol);
      }



      if NOT IsClass(self,&DM)
         AND (Send(poOwner,@GetRegion) <> Send(oNew_room,@GetRegion))
      {
