      ret_val = Send(SYS,@UtilGoNearSquare,#what=self,#where=oNew_room,
                     #new_row=iRow,#new_col=iCol,
                     #fine_row=iFineRow,#fine_col=iFineCol,
                     #max_distance=2);

      if ret_val
      {
         if logged_off
         {
