      lRecent_mail = $;
      iRemoved = 0;
      for lNew_mail in plNew_mail
      {

	 iTime = Nth(lNew_mail,2);
	 if (iTime > iCutoff_time)
	 {
	    lRecent_mail = Cons(lNew_mail,lRecent_mail);
	 }
	 else
