{
      local i, iFlags, iIntensity, iColor, bHasLight,
            iTorchColor, iTorchIntensity, iGlowColor, iGlowIntensity,
            bHasSteady;

      if poIllusion_set <> $
      {
         if NOT Send(poIllusion_set,@IllusionGetLightingInformation,#who=self)
         {

            propagate;
         }

         return;
      }


      iTorchColor = 0;
      iTorchIntensity = 0;
      iGlowColor = 0;
      iGlowIntensity = 0;

      for i in plUsing
      {
         if Send(i,@IsFlickering)
         {
            iTorchColor = Send(i,@GetLightColor);
            iTorchIntensity = Send(i,@GetLightIntensity);
         }

         if Send(i,@IsGlowing)
         {
            iGlowColor = Send(i,@GetLightColor);
            iGlowIntensity = Send(i,@GetLightIntensity);
         }
      }


      iFlags = LIGHT_FLAG_ON | LIGHT_FLAG_DYNAMIC;
      iIntensity = 0;
      iColor = 0;
      bHasLight = FALSE;
      bHasSteady = FALSE;

      if iGlowColor <> 0
      {
         iColor = iGlowColor;
         iIntensity = iGlowIntensity;
         bHasLight = TRUE;
         bHasSteady = TRUE;
      }

      if iTorchColor <> 0
      {
         if bHasLight
         {

            iColor = Send(self,@MixLightColors,
                          #iColor1=iColor,#iColor2=iTorchColor);
            if iTorchIntensity > iIntensity
            {
               iIntensity = iTorchIntensity;
            }
         }
         else
         {
            iColor = iTorchColor;
            iIntensity = iTorchIntensity;
         }

         bHasLight = TRUE;
      }

      if bHasLight
      {

         if NOT bHasSteady
         {
            iFlags = iFlags | LIGHT_FLAG_WAVERING;
         }

         AddPacket(2,iFlags);
         AddPacket(1,iIntensity);
         AddPacket(2,iColor);

         return;
      }

      propagate;
   }

