               while i <= iNumItemsInventory
                     AND NOT Send(poGhostedPlayer,@DropItem,#index=i,
                                  #targetGhost=self)
               {
                  i = i + 1;
               }



               if i > Send(poGhostedPlayer,@GetNumItemsInInventory)
               {
                  LossCounter = 1;
               }
            }

            LossCounter = LossCounter - 1;
