            LossCounter = (LossCounter + 1);
         }

         if Send(poGhostedPlayer,@CheckPlayerFlag,#flag=PFLAG_MURDERER)
         {
            BaseLossAmount = 2;
         }
         else
         {
            BaseLossAmount = 1;
         }



         if (LossCounter > Length(lSpells))
         {
            i = 0;

