            if length(nth(plPlayerRestrict2,i)) > 1 {
               if parm1 <> $ { setNth(nth(plPlayerRestrict2,i),2,parm1); }
               if length(nth(plPlayerRestrict2,i)) > 2 {
                  if parm2 <> $ { setNth(nth(plPlayerRestrict2,i),3,parm2); }
               }
            }
            return TRUE;
         }
      }
   }
   return FALSE;
}

