                         #index=piQuestNodeTemplateIndex);

            if iType = QN_TYPE_MONSTER
            {
               piStatus = QN_STATUS_IN_PROGRESS;

               return TRUE;
            }

            if iType <> QN_TYPE_MONSTER_ITEMCLASS
            {
               Debug("Questnode of non-monster type processed monster death.");

               return TRUE;
            }

            if pCargo = $
            {
