                    length(plCorNothRIDs) + length(plBarloqueRIDs) - 5;
      iPrincessFlags = ((iPrincesspower * iTotalFlags) / iTotalPower);
      iDukeFlags = ((iDukePower * iTotalFlags) / iTotalPower);
