	{
		penaltylist = [];
	}

	lThisQuestNodeTemplate = [ plDefaultNPCList, NPC_modifier, questnode_type,\
		cargolist, monsterlist, prizelist, penaltylist, CreateString(), CreateString(), CreateString(), timelimit ];


