         {
            for j in Nth(i,2)
            {   
               if first(j) = level
               {
                       lNode = Nth(j,2) + 1;
                       setNth(j,2,lNode);
                       return;
               }
            }


            lNode = Cons([level,1],Nth(i,2));
            SetNth(i,2,lNode);

            return;
         }
      }


      plAbility_totals = cons( [ school, [[ level, 1]]], plAbility_totals);
      return;
   }

