               else
               {

                  Send(where,@NewHold,#what=what,#new_row=new_row,#new_col=new_col,
                       #fine_row=fine_row,#fine_col=fine_col);
               }


               Send(where,@SomethingMoved,#what=what,#new_row=new_row,#new_col=new_col,#fine_row=fine_row,#fine_col=fine_col);
            }

