         return XLAT_TO_DGREEN;
      }

      if Xlat > 124 AND Xlat < 128
      {
         return XLAT_TO_BLACK;
      }

      Xlat = Xlat - XLAT_BASE_VALUE;
      Xlat = Xlat / 11;

      return XLat;
   }

{
