      {
         Xlat = xlat - 121;
         xlat = xlat mod 3;
         if xlat = 0
         {
            return XLAT_TO_SKIN4;
         }
         else
         {
            return xlat;
         }
      }

      Xlat = Xlat - XLAT_BASE_VALUE;
      Xlat = Xlat mod 11;

      return XLat;
