{
      local lCopy, i, iElem;

      lCopy = $;
      if source <> $
      {
         i = length(source);
         while i > 0
         {
            iElem = nth(source, i);
            if IsList(iElem)
            {
               lCopy = Cons(Send(self,@ListCopy,#source=iElem),lCopy);
            }
            else
            {
               lCopy = Cons(iElem,lCopy);
            }

            i = i - 1;
         }
      }

      return lCopy;
